mapper.select:
SELECT COUNT(*)
FROM BLIND_CHAT_ROOM r
JOIN BLIND_MATCHING m ON m.BLIND_MATCHING_SEQ = r.BLIND_MATCHING_SEQ
JOIN MEMBER mem ON mem.MEMBER_SEQ IN (m.MEMBER_SEQ_1, m.MEMBER_SEQ_2)
WHERE r.BLIND_CHAT_ROOM_SEQ = #{roomSeq}
  AND mem.LOGIN_ID = #{loginId}

mapper.update:
UPDATE BLIND_MATCHING

    SET VOTE_1 = #{vote}
    SET VOTE_2 = #{vote}

WHERE BLIND_MATCHING_SEQ = #{blindMatchingSeq}

    AND (VOTE_1 IS NULL OR VOTE_1 = 'GO')
    AND VOTE_1 IS NULL
    AND (VOTE_2 IS NULL OR VOTE_2 = 'GO')
    AND VOTE_2 IS NULL

UPDATE BLIND_MATCHING
SET STATUS = #{status}
WHERE BLIND_MATCHING_SEQ = #{blindMatchingSeq}

UPDATE AI_REPLY_SUGGESTION
SET SELECTED_YN = 'Y',
    EDITED_YN = #{editedYn}
WHERE AI_REPLY_SUGGESTION_SEQ = #{seq}
  AND SELECTED_YN = 'N'
